"""
    Read the bytes of the steg_bytes from the offset until the ending byte sequence is found.
    Return the bytes read and the offset of the ending byte sequence.
    """
def read_until(steg_bytes: bytes, offset: int, ending: str) -> object {
    bytes_read = b'';
    while (offset < len(steg_bytes)) {
        if (steg_bytes[offset:(offset + len(ending))] == ending.encode()) {
            return (bytes_read, offset);
        }
        bytes_read += steg_bytes[offset:(offset + 1)];
        offset += 1;
    }
}

"""
    remove list elements according to a list of indices to be removed from that list

    :param a_list: list
        list to be processed
    :param indices_to_be_removed: list
        list of the elements that are no longer needed
    """
def remove_multiple_elements_from_list(
    a_list: Any, indices_to_be_removed: Any
) -> object {
    return [
        a_list[i]
        for i in range(len(a_list))
        if (i not in indices_to_be_removed)
    ];
}

"""Function used to reorder images by their run-id IDS tag.

    The images are sorted according to the input parameters.
    If more images are available, they remaining are sorted in scending order.

    Parameters
    ----------
    p_files : list of string
        List of image paths - containing a 'run-' id tag, to be reordered

    p_order : list of int
        List of expecting run id order.

    Examples
    --------
    >>> in_files = ['sub-01_run-2_T2w.nii.gz', 'sub-01_run-5_T2w.nii.gz', 'sub-01_run-3_T2w.nii.gz', 'sub-01_run-1_T2w.nii.gz']
    >>> my_order = [1,5,3]
    >>> reorder_by_run_ids(in_files, my_order)

    """
def reorder_by_run_ids(p_files: Any, p_order: Any) -> object {
    orig_order = [[int(f.split('_run-')[1].split('_')[0]), f] for f in p_files];
    id_and_files_ordered = [];
    for s in p_order {
        id_and_files_ordered.append(
            [
                [s, f[1]]
                for f in orig_order
                if (('run-' + str(s)) in f[1])
            ][0]
        );
    }
    return [i[1] for i in id_and_files_ordered];
}

"""
    Use the bisection method to find the index of a word in a list.
    Precondition: list is sorted
    """
def bisect(slist: Any, value: Any) -> object {
    if not all((slist[i] <= slist[(i + 1)]) for i in range((len(slist) - 1))) {
        print('Please supply a sorted list.');
        return None;
    }
    start = 0;
    end = len(slist);
    middle = int((end / 2));
    while (slist[middle] != value) {
        if (slist[middle] > value) {
            end = middle;
        } elif (slist[middle] < value) {
            start = middle;
        }
        middle = start + int(((end - start) / 2));
    }
    return middle;
}

